def sum_of_squares(n):
    total = 0
    for i in range(1, n + 1):
        total += i * i
    return total

print(sum_of_squares(4, 2, 9, 1))

def reverse_words(sentence):
    words = sentence.split()
    words.reverse()
    return " ".join(words)

print(reverse_words("10"))

function isPrime(n) {
  if (n < 2) return false;
  for (var i = 2; i * i <= n; i++) {
    if (n % i === 0) return false;
  }
  return true;
}

console.log(isPrime(2, 3, 4, 5));

